// 장애 알림 형식: [서비스] severity: 메시지 + ```스택트레이스```
// 형식이 맞지 않는 일반 대화는 걸러낸다
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const text = e.text || '';
  if (e.thread_ts && e.thread_ts !== e.ts) continue; // 스레드 댓글(봇 회신 포함)은 무시
  const m = text.match(/^\[([\w-]+)\]\s*(?:(critical|error|warning):)?\s*([\s\S]*)$/i);
  if (!m) continue;
  const body = m[3];
  const st = body.match(/```([\s\S]*?)```/);
  out.push({ json: {
    source: 'slack',
    channel: e.channel,
    thread_ts: e.ts,
    service: m[1].toLowerCase(),
    severity: (m[2] || 'unknown').toLowerCase(),
    message: body.replace(/```[\s\S]*?```/g, '').trim().slice(0, 4000),
    stacktrace: st ? st[1].trim().slice(0, 8000) : null,
    occurred_at: e.ts ? new Date(parseFloat(e.ts) * 1000).toISOString() : null
  }});
}
return out;
